const keywords = ['ai','machine learning','ml','llm','automation','n8n','langchain','rag','python','data scientist','computer vision','nlp'];
let raw = $input.all().map(i => i.json);
let jobs = [];
if (raw.length === 1 && Array.isArray(raw[0].data)) jobs = raw[0].data; // ArbeitNow: { data: [...] }
else if (raw.length === 1 && Array.isArray(raw[0].jobs)) jobs = raw[0].jobs; // Remotive: { jobs: [...] }
else jobs = raw; // RemoteOK: array of jobs
jobs = jobs.map(j => ({
  title: j.title || j.position || '',
  company: j.company_name || j.company || '',
  url: j.url || '',
  tags: Array.isArray(j.tags) ? j.tags.join(' ') : (j.tags || ''),
})).filter(j => j.title && j.url);
const matches = jobs.filter(j => {
  const hay = (j.title + ' ' + j.tags).toLowerCase();
  return keywords.some(k => {
    if (k.length <= 3) return new RegExp('\\b' + k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b').test(hay);
    return hay.includes(k);
  });
}).slice(0, 8);
const dateStr = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Karachi', day: '2-digit', month: 'short', year: 'numeric' }).format(new Date());
let msg = '\uD83E\uDD16 Remote AI Jobs \u2014 ' + dateStr + '\n\n';
if (matches.length === 0) {
  msg += 'No matching AI/automation roles found today.\n';
} else {
  matches.forEach((j, i) => { msg += (i + 1) + '. ' + j.title + ' \u2014 ' + j.company + '\n' + j.url + '\n\n'; });
}
msg += 'Filtered for AI/automation roles. Reply if you want details on any role.';
return [{ json: { message: msg, count: matches.length, jobs: matches.map(j => ({ title: j.title, company: j.company, url: j.url })) } }];

